local K={14,197,44,232,227,155,184,198}
local char,byte,concat=string.char,string.byte,table.concat
local bxor
if bit32 and bit32.bxor then
 bxor=bit32.bxor
elseif bit and bit.bxor then
 bxor=bit.bxor
else
 bxor=function(a,b)
  local r,p=0,1
  a=a%256
  b=b%256
  for _=1,8 do
   local x,y=a%2,b%2
   if x~=y then r=r+p end
   a=(a-x)/2
   b=(b-y)/2
   p=p*2
  end
  return r
 end
end
local function dec(s)
 local o={}
 for i=1,#s do
  o[i]=char(bxor(byte(s,i),K[((i-1)%#K)+1]))
 end
 return concat(o)
end
